        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            long[][] ndp = new long[n + 1][n + 1];
            for (int j = 0; j <= i; j++) {
                for (int c = 0; c <= i; c++) {
                    if (dp[j][c] == 0) continue;
                    // Case 1: new segment doesn't overlap with current point
                    ndp[j][c] = (ndp[j][c] + dp[j][c] * (j + 1)) % MOD;
                    // Case 2: new segment overlaps, adding to coverage
                    if (j + 1 <= n) {
                        ndp[j + 1][c] = (ndp[j + 1][c] + dp[j][c] * (n - j)) % MOD;
                    }
                }
            }
            dp = ndp;
        }

        long ans = 0;
        for (int c = k; c <= n; c++) {
            ans = (ans + dp[n][c]) % MOD;
        }
        ans = ans * l % MOD;
        System.out.println(ans);
    }
}
