                long c = comb(n - m, i) * pow(-2, i, MOD) % MOD;
                int a = m + i;
                long beta = fact2[a] * fact2[a] % MOD * inv_fact2[2 * a + 1] % MOD;
                sum = (sum + c * beta) % MOD;
            }
            term = term * sum % MOD;
            I = (I + term) % MOD;
        }

        long ans = l % MOD * I % MOD;
        ans = (ans % MOD + MOD) % MOD;
        System.out.println(ans);
    }
