import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static final int MAXN = 2005;

    static long[] fact = new long[MAXN];
    static long[] invFact = new long[MAXN];
    static long[] inv = new long[MAXN];

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MAXN; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[MAXN - 1] = modInverse(fact[MAXN - 1], MOD);
        for (int i = MAXN - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
        inv[1] = 1;
        for (int i = 2; i < MAXN; i++) {
            inv[i] = MOD - MOD / i * inv[MOD % i] % MOD;
        }
    }

    static long modInverse(long a, long m) {
        long m0 = m, t, q;
        long x0 = 0, x1 = 1;
        if (m == 1) return 0;
        while (a > 1) {
            q = a / m;
            t = m;
            m = a % m;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }
        if (x1 < 0) x1 += m0;
        return x1;
    }

    static long C(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long l = Long.parseLong(st.nextToken());

        precompute();

        long ans = 0;
        for (int i = 0; i <= n; i++) {
            long ways = C(n, i);
            ways = ways * modInverse(2, MOD) % MOD;
            ways = ways * modInverse(2, MOD) % MOD;
            long prob = ways;
            long length = (l % MOD) * prob % MOD;
            if (i >= k) {
                ans = (ans + length) % MOD;
            }
        }

        System.out.println(ans);
    }
}
